# Stock in place (release without translated stock code): cfg "stock_in_place" lists reconstructed module stems whose
# stock functions run unmodified from the user's file. Their entries stay stock, their adapter source leaves the link and
# their MOD055 palette sites keep the parent bytes (the theme lives in the stock body). Each adapter wraps one module.
import re as _re
from pathlib import Path as _Path
_ROOT=_Path(__file__).resolve().parents[3]
def _module(src):
 return _re.findall(r'#include\s+"[^"]*reconstructed/nds/([^"/]+)\.c"',(_ROOT/src).read_text())
def _reverted(cfg):
 keep=set((cfg or {}).get('stock_in_place',()))
 return [s for s in C_SOURCES if keep and set(_module(s))<=keep and _module(s)]
def _reverted_entries(cfg):
 out={int(x,16) for s in _reverted(cfg) for x in _re.findall(r'nds_bulk_([0-9a-f]{5})\b',(_ROOT/s).read_text())}&set(HOOKED)
 if 'midi_program_dispatch' in {m for s in _reverted(cfg) for m in _module(s)}:out.add(0x16254)   # entered via the midi_context asm label
 return out
def hooked(cfg):
 gone=_reverted_entries(cfg);return tuple(a for a in HOOKED if a not in gone)
def c_sources(cfg):
 gone=set(_reverted(cfg));return tuple(s for s in C_SOURCES if s not in gone)+((ES_SOURCE,) if _es_foot(cfg) else ())
def c_entries(cfg):
 return tuple(f'nds_bulk_{a:05x}'for a in hooked(cfg) if a!=0x16254)+(('nds_bulk_midi_context_c',) if _midi_c(cfg) else ())+(tuple(f'gp50_es_foot_{e:05x}' for e in ES_FOOT) if _es_foot(cfg) else ())
def superseded(cfg):
 stems={m for s in _reverted(cfg) for m in _module(s)}
 from ..stock_in_place import inside
 gone=_reverted_entries(cfg)
 return {a:v for a,v in SUPERSEDED.items() if not (_re.search(r'(\S+)\.c$',v) and _re.search(r'(\S+)\.c$',v).group(1) in stems) and not inside(a,gone)}
def _check_stock_bodies(c):
 """Every reverted body: parent bytes equal stock except its declared palette sites (4-byte windows)."""
 from ..holes import stock_facts
 stems={m for s in _reverted(c.cfg) for m in _module(s)}
 from ..stock_in_place import inside
 sites=[a for a in SUPERSEDED if inside(a,_reverted_entries(c.cfg))]   # palette and parent call hooks; build.generate checks the calls are re-patched
 stock=(_ROOT/'work/v110/decoded_b.bin').read_bytes();_,_,bodies,_=stock_facts()
 for e in sorted(_reverted_entries(c.cfg)):
  body=next((r for r in bodies.get(e,[]) if r[0]<=e<=r[1]),None)
  if not body:raise ValueError(f'stock_in_place entry {e:#x}: no function body in the index')
  from ..stock_in_place import theme_sites
  from ..stock_in_place import hook_windows,parent_edits
  from ..build import feature
  theme=theme_sites(stock,c.parent_b,body[0],body[1])|hook_windows()|parent_edits([feature(f) for f in c.enabled])   # hooks: build.generate checks they are re-patched
  bad=[a for a in range(body[0],body[1]+1) if c.parent_b[a-0x10000]!=stock[a-0x10000] and a not in theme and not any(s<=a<s+4 for s in sites)]
  if bad:raise ValueError(f'stock_in_place entry {e:#x}: parent differs from stock at {[hex(x) for x in bad[:4]]}')
def patches(c):
 if _reverted(c.cfg):_check_stock_bodies(c)
 live=set(hooked(c.cfg))
 out=[(a,f'j {c.labels[f"nds_bulk_{a:05x}"]:#x}',f'bulk application C {a:05x}')for a in HOOKED if a in live and a not in (0x1cc5c,0x1d2bc,0x1d2c8)]
 if _es_foot(c.cfg):out+=[(e,f'j {c.labels[f"gp50_es_foot_{e:05x}"]:#x}',f'effect-set footswitch {e:05x}: A/B check, then stock handler') for e in ES_FOOT]
 return out
